-- ============================================================
-- Riyadh Chamber Management — Seed Data (OPTIONAL)
-- ============================================================
-- Run this in the Supabase SQL Editor ONLY if you want to load
-- the demo/dummy data. Uses ON CONFLICT DO NOTHING so it will
-- NOT overwrite existing records.
-- ============================================================

-- ============ TASKS ============
ON CONFLICT (task_id) DO NOTHING;

-- ============ MEETINGS ============
ON CONFLICT (meeting_id) DO NOTHING;

-- ============ PROJECTS ============
ON CONFLICT (project_id) DO NOTHING;

-- ============ LOOKUPS ============
  "departments": ["إدارة البيانات","إدارة المتابعة والتمكين","إدارة اللجان القطاعية","إدارة التعاون الدولي","مكتب الأمين العام","مكتب نائب الأمين العام","المنشآت العائلية","إدارة أخرى"],
  "taskTypes": ["داخلي","خارجي"],
  "taskStatuses": ["مكتملة","قيد التنفيذ","مغلقة"],
  "meetingTypes": ["حضوري","عن بعد"],
  "meetingClassifications": ["داخلي","خارجي","إداري"],
  "projectTypes": ["مبادرة","برنامج","مشروع","شراكة"],
  "projectStatuses": ["لم تبدأ","قيد التنفيذ","مكتملة"]
}'::jsonb)
ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data;
